function raycast(lon: number, lat: number, ring: [number, number][]): boolean {
  let inside = false;
  const n = ring.length;
  let j = n - 1;
  for (let i = 0; i < n; i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (
      yi > lat !== yj > lat &&
      lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi
    ) {
      inside = !inside;
    }
    j = i;
  }
  return inside;
}
export function coordinateToRegion(lon: number, lat: number): string {
  //pre-filter for Lithuanian borders
  if (lon < 20.9 || lon > 26.9 || lat < 53.9 || lat > 56.5) {
    return 'Nenustatyta';
  }
  for (const county of LT_COUNTIES) {
    if (raycast(lon, lat, county.ring)) {
      return county.name;
    }
  }
  return 'Nenustatyta';
}
